const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helpers
  const evalPromise = (obj) => new Promise((resolve, reject) => obj.evaluate(resolve, reject));

  // Geometry & Time Definitions
  const center = ee.Geometry.Point([80.0, 37.5]); // Taklamakan Desert near Hotan
  const region = center.buffer(30000); // 30 km radius
  const scale = 1000;

  const win1 = {start: '2020-02-18', end: '2020-02-28', label: 'Feb23±5d'};
  const win2 = {start: '2020-04-24', end: '2020-05-04', label: 'Apr29±5d'};

  // Sentinel-2 processors
  function maskS2sr(img) {
    const qa = img.select('QA60');
    const mask = qa.bitwiseAnd(1 << 10).eq(0).and(qa.bitwiseAnd(1 << 11).eq(0));
    return img.updateMask(mask);
  }
  function s2NdviComposite(start, end) {
    const col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(start, end)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
      .map(maskS2sr)
      .map(img => img.normalizedDifference(['B8', 'B4']).rename('NDVI'));
    return {col: col, img: col.median(), sensor: 'Sentinel-2'};
  }

  // Landsat 8 processors (fallback if empty)
  function maskL8(img) {
    const qa = img.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0) // cloud
      .and(qa.bitwiseAnd(1 << 4).eq(0))      // cloud shadow
      .and(qa.bitwiseAnd(1 << 2).eq(0))      // cirrus
      .and(qa.bitwiseAnd(1 << 5).eq(0));     // snow
    return img.updateMask(mask);
  }
  function l8NdviComposite(start, end) {
    const colRaw = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(region)
      .filterDate(start, end);
    const col = colRaw
      .map(maskL8)
      .map(img => {
        const sr = img.select(['SR_B4','SR_B5']).multiply(0.0000275).add(-0.2);
        return sr.normalizedDifference(['SR_B5','SR_B4']).rename('NDVI');
      });
    return {col: col, img: col.median(), sensor: 'Landsat-8'};
  }

  async function getWindowMetrics(win) {
    // Try Sentinel-2
    let s2 = s2NdviComposite(win.start, win.end);
    let s2Size = await evalPromise(s2.col.size());
    let sensorUsed = 'Sentinel-2';
    let img = s2.img;
    let sizeUsed = s2Size;

    // If empty, try Landsat 8
    if (!s2Size || s2Size === 0) {
      const l8 = l8NdviComposite(win.start, win.end);
      const l8Size = await evalPromise(l8.col.size());
      if (!l8Size || l8Size === 0) {
        return {empty: true, msg: `${win.label}: No images in S2 or L8.`};
      }
      sensorUsed = 'Landsat-8';
      img = l8.img;
      sizeUsed = l8Size;
    }

    // Compute metrics
    const totalCount = ee.Image.constant(1).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('constant');

    const validCount = img.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI');

    const meanNdvi = img.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI');

    const coverCount = img.gt(0.2).selfMask().reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI');

    const [tot, val, mean, cov] = await Promise.all([
      evalPromise(totalCount), evalPromise(validCount), evalPromise(meanNdvi), evalPromise(coverCount)
    ]);

    if (val === 0) {
      return {noValid: true, msg: `${win.label}: 0 valid pixels after masking.`};
    }

    const coverFrac = (val && cov != null) ? (cov / val) : null;

    return {
      sensor: sensorUsed,
      images: sizeUsed,
      totalCount: tot,
      validCount: val,
      meanNdvi: mean,
      coverFrac: coverFrac
    };
  }

  try {
    console.log(`Region: center [80.0, 37.5], radius 30 km; scale ${scale} m`);

    const m1 = await getWindowMetrics(win1);
    if (m1.empty) { console.log(m1.msg); console.log('C1'); return; }
    if (m1.noValid) { console.log(m1.msg); console.log('C2'); return; }

    const m2 = await getWindowMetrics(win2);
    if (m2.empty) { console.log(m2.msg); console.log('C1'); return; }
    if (m2.noValid) { console.log(m2.msg); console.log('C2'); return; }

    // Validate values
    const invalid = (v) => (v === null || v === undefined || Number.isNaN(v));
    if (invalid(m1.coverFrac) || invalid(m2.coverFrac) || invalid(m1.meanNdvi) || invalid(m2.meanNdvi)) {
      console.log('Calculation produced null/NaN.');
      console.log('C3');
      return;
    }
    if (m1.coverFrac < 0 || m1.coverFrac > 1 || m2.coverFrac < 0 || m2.coverFrac > 1) {
      console.log('Cover fraction out of [0,1].');
      console.log('C3');
      return;
    }

    // Print concise evidence
    const vf1 = (m1.validCount / m1.totalCount) * 100.0;
    const vf2 = (m2.validCount / m2.totalCount) * 100.0;
    console.log(`${win1.label}: Sensor=${m1.sensor}, Images=${m1.images}`);
    console.log(`${win1.label}: Valid px ${m1.validCount}/${m1.totalCount} (${vf1.toFixed(1)}%), Mean NDVI=${(+m1.meanNdvi).toFixed(3)}, Cover>0.2=${m1.coverFrac.toFixed(3)}`);
    console.log(`${win2.label}: Sensor=${m2.sensor}, Images=${m2.images}`);
    console.log(`${win2.label}: Valid px ${m2.validCount}/${m2.totalCount} (${vf2.toFixed(1)}%), Mean NDVI=${(+m2.meanNdvi).toFixed(3)}, Cover>0.2=${m2.coverFrac.toFixed(3)}`);

    const diff = m2.coverFrac - m1.coverFrac;
    console.log(`Cover change (Apr - Feb): ${diff.toFixed(3)}`);

    // Final Answer
    if (diff > 0.005) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
